import pandas as pd

labels = pd.DataFrame(
    {"route": [10, 10], "ts": pd.to_datetime(["2024-01-05", "2024-01-20"]), "late": [0, 1]}
)
features = pd.DataFrame(
    {
        "route": [10, 10, 10],
        "ts": pd.to_datetime(["2024-01-01", "2024-01-10", "2024-01-25"]),
        "late_rate": [0.1, 0.3, 0.9],
    }
)
latest = features.sort_values("ts").groupby("route").tail(1)[["route", "late_rate"]]
print("latest join:", labels.merge(latest, on="route")["late_rate"].tolist())
as_of = pd.merge_asof(labels.sort_values("ts"), features.sort_values("ts"), on="ts", by="route")
print("as-of join:", as_of["late_rate"].tolist())

import hashlib

published = b"wheel contents v1.2.0"
tampered = b"wheel contents v1.2.0 plus extra code"
lock = {"name": "routing-lib", "version": "1.2.0", "sha256": hashlib.sha256(published).hexdigest()}


def install(name, version, data, require_hash):
    if (name, version) != (lock["name"], lock["version"]):
        return "rejected: version"
    if require_hash and hashlib.sha256(data).hexdigest() != lock["sha256"]:
        return "rejected: hash mismatch"
    return "installed"


for require_hash in (False, True):
    print(
        "require hash", require_hash, "->", install("routing-lib", "1.2.0", tampered, require_hash)
    )
